import { Column, CreateDateColumn, Entity, Index, JoinColumn, ManyToOne, PrimaryColumn, UpdateDateColumn } from 'typeorm';
import { Role, TaskAutomation, TaskStatus, TaskType } from '@app/common';
import { WorkflowRun } from '../runs/workflow-run.entity';

/**
 * A task of a run, or an ad-hoc task (runId null). `dependsOn` holds the ids of the
 * tasks that must be DONE or SKIPPED before this one leaves BLOCKED.
 * The id is generated by the engine so a whole run can be linked before insertion.
 */
@Entity('tasks')
@Index(['status'])
@Index(['runId'])
export class Task {
  @PrimaryColumn('uuid')
  id: string;

  @Column({ type: 'uuid', nullable: true })
  runId: string | null;

  @ManyToOne(() => WorkflowRun, (run) => run.tasks, { onDelete: 'CASCADE', nullable: true })
  @JoinColumn({ name: 'runId' })
  run?: WorkflowRun | null;

  @Column({ type: 'uuid', nullable: true })
  workflowId: string | null;

  /** Template task id this task was created from. */
  @Column({ type: 'varchar', length: 64, nullable: true })
  defId: string | null;

  @Column({ type: 'varchar', length: 160 })
  title: string;

  @Column({ type: 'text', nullable: true })
  description: string | null;

  @Column({ type: 'enum', enum: TaskType, default: TaskType.MANUAL })
  type: TaskType;

  @Column({ type: 'enum', enum: TaskStatus, default: TaskStatus.TODO })
  status: TaskStatus;

  @Column({ type: 'enum', enum: Role, nullable: true })
  assigneeRole: Role | null;

  @Column({ type: 'varchar', length: 64, nullable: true })
  assigneeEmployeeId: string | null;

  @Column({ type: 'varchar', length: 120, nullable: true })
  assigneeName: string | null;

  @Column({ type: 'jsonb', default: () => "'[]'" })
  dependsOn: string[];

  @Column({ type: 'jsonb', nullable: true })
  automation: TaskAutomation | null;

  /** From the template; dueAt = moment the task becomes TODO + dueInHours. */
  @Column({ type: 'int', nullable: true })
  dueInHours: number | null;

  @Column({ type: 'timestamptz', nullable: true })
  dueAt: Date | null;

  @Column({ type: 'timestamptz', nullable: true })
  startedAt: Date | null;

  @Column({ type: 'timestamptz', nullable: true })
  completedAt: Date | null;

  @Column({ type: 'varchar', length: 120, nullable: true })
  completedByName: string | null;

  @Column({ type: 'text', nullable: true })
  notes: string | null;

  /** AUTOMATION result or error message. */
  @Column({ type: 'text', nullable: true })
  output: string | null;

  /** Order of the task in its template (stable display order inside a run). */
  @Column({ type: 'int', default: 0 })
  sortOrder: number;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updatedAt: Date;
}
